import { GameEngine } from "../game";
import { GameEvent } from "../../types";
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import { SequenceSystem } from "./visuals/SequenceSystem";
import { EventHUDMapper } from "./visuals/EventHUDMapper";
import { EventVFXMapper } from "./visuals/EventVFXMapper";
import { VisualMath } from "../math/VisualMath";
import { SKILL_SEQUENCES } from "../../data/vfx/SkillSequences";
import { HexUtils } from "../utils";

export class VisualEventListener {
    private hudMapper: EventHUDMapper;
    private vfxMapper: EventVFXMapper;
    constructor() {
        this.hudMapper = new EventHUDMapper();
        this.vfxMapper = new EventVFXMapper();
    }
    public reset() { this.hudMapper.reset(); }
    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        events.forEach(event => {
            this.hudMapper.process(event, engine, hud, grid, camera);
            if (event.type === 'CAST_START' && event.skill) {
                const sequence = SKILL_SEQUENCES[event.skill.id];
                if (sequence) {
                    const target3D = VisualMath.resolveTargetPoint(event.targetId || "", engine);

                    // SSOT FIX: If target is ground (no unit ID or generic), ensure correct Z
                    if (target3D.z < -9000) {
                        target3D.x = event.pos.x;
                        target3D.y = event.pos.y;

                        // Fix: Use event position to find hex and get terrain height
                        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                        target3D.z = grid.getTerrainHeight(hex.q, hex.r, engine) + 20; 
                    }
                    SequenceSystem.run(sequence, target3D, engine, vfx, event.sourceId);
                    return; 
                }
            }
            this.vfxMapper.process(event, engine, vfx, grid, camera);
        });
    }
}

import { Particle } from "./state";
import { PHYSICS } from "../../../constants";

const DEFAULT_GRAVITY = 2500; 

export class VFXPhysics {
    public static update(p: Particle, dt: number, getTerrainHeight?: (x: number, y: number) => number) {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.rotation += p.vRotation * dt;

        // FIX: Add GIANT_HEX to physical types so it collides with ground (Heaven Fall logic)
        const isPhysical = ['DEBRIS', 'SHARD', 'SPRITE', 'ROCK', 'CHIP', 'RUBBLE', 'GIANT_HEX'].includes(p.type);
        const currentGroundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

        if (isPhysical) {
            const g = p.gravity !== undefined ? p.gravity : DEFAULT_GRAVITY;
            p.vz -= g * dt;
            p.z += p.vz * dt;

            const floorLevel = currentGroundH + 2;

            if (p.z < floorLevel) {
                p.z = floorLevel;

                if (Math.abs(p.vz) > 120) {
                    p.vz = -p.vz * 0.45;
                    p.vx *= 0.7;
                    p.vy *= 0.7;
                    p.vRotation *= 0.6;
                } else {
                    p.vz = 0;
                    p.vx *= 0.2;
                    p.vy *= 0.2;
                    p.vRotation = 0;
                }
            }
        } else {
            p.z += p.vz * dt;

            if (p.drag !== undefined) {
                const f = 1 - p.drag;
                p.vx *= f; p.vy *= f; p.vz *= f;
            } else {
                p.vx *= 0.94;
                p.vy *= 0.94;
                p.vz *= 0.94;
            }

            if (p.z < currentGroundH) {
                p.z += (currentGroundH - p.z) * 0.1;
            }
        }

        p.lastGroundHeight = currentGroundH;
    }
}

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const GROUND_PROJECTION_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

export class VFXRenderer {
    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        // Culling Padding needs to be huge vertically to account for Z-axis (Heaven Fall)
        const PAD_X = 1200;
        const PAD_Y_TOP = 2500; // Look way up for meteors
        const PAD_Y_BOT = 1200;

        if (viewport) {
            const { width, height, camera } = viewport;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - PAD_X;
            cullMaxX = camera.x + (viewW / 2) + PAD_X;
            cullMinY = camera.y - (viewH / 2) - PAD_Y_TOP;
            cullMaxY = camera.y + (viewH / 2) + PAD_Y_BOT;
        }

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1500) return;

            const op = renderList.next();
            op.type = RenderOpType.VFX;

            const isGroundLocked = GROUND_PROJECTION_TYPES.has(p.type);
            const isUlt = (p as any).pIsUlt || p.type === 'GIANT_HEX' || p.type === 'MAGIC_CIRCLE';

            op.y = p.y + offset + (isGroundLocked ? 2 : 0); 
            op.z = isGroundLocked ? (p.z + 5) : p.z; 
            op.pIsUlt = isUlt; // 核心：傳遞奧義標記至排序器

            op.particle = p;
            op.vProgress = 1 - (p.life / p.maxLife);
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = d.y + offset + 1; 
            op.z = 2; 
            op.tx = d.x; op.ty = d.y + offset; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }
}

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { VisualMath, Point3D } from "../../math/VisualMath";

// Sub-Handlers
import { CombatVFXHandler } from "./handlers/CombatVFXHandler";
import { UnitVFXHandler } from "./handlers/UnitVFXHandler";
import { CinematicVFXHandler } from "./handlers/CinematicVFXHandler";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Resolve Spatial Context
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine);

        const groundHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const groundZ = grid.getTerrainHeight(groundHex.q, groundHex.r, engine);

        if (!event.targetId) target.z = groundZ + 20;

        // 2. Route to specialized atomic handlers
        switch (event.type) {
            case 'DAMAGE': 
            case 'PROJECTILE_HIT': 
            case 'IMPACT_AOE':
                CombatVFXHandler.handle(event, vfx, camera, target, groundZ);
                break;

            case 'DEATH':
            case 'SPAWN':
            case 'CAST_BREAK':
                UnitVFXHandler.handle(event, engine, vfx, camera, origin, groundZ);
                break;

            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                CinematicVFXHandler.handle(event, engine, vfx, origin, target);
                break;

            case 'HAZARD_SPAWN':
                if (event.text) { // We stored VFX ID in 'text' field
                    vfx.playEffect(event.text, event.pos.x, event.pos.y, groundZ);
                }
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine): Point3D {
        if (agentId) {
            const agent = engine.agents.find(a => a.id === agentId);
            if (agent) return VisualMath.getUnitAnchor(agent, engine);
        }
        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = engine.map.getTerrainHeight(hex.q, hex.r);
        return { x: defaultX, y: defaultY, z: terrainH };
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../../../math/VisualMath";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";

export class CombatVFXHandler {

    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {
        const damage = Math.abs(event.value || 0);
        const isCrit = damage > 150;
        const isMassive = damage > 400;

        let intensity = 1.0;
        if (isCrit) intensity = 1.6;
        if (isMassive) intensity = 2.5;

        if (event.type === 'DAMAGE') {
            if (!event.skill?.projectileSpeed) {
                if (event.skill?.ccType !== 'DOT') {
                    // 核心受擊：播放命中特效
                    this.playImpact(event, vfx, target, groundZ, intensity);
                    camera.addTrauma(isMassive ? 0.45 : (isCrit ? 0.3 : 0.12));
                } else {
                    vfx.playEffect('FX_STATUS_BURN_LOOP', target.x, target.y, target.z, event.color);
                }
            }
            return;
        }

        if (event.type === 'PROJECTILE_HIT') {
            if (event.skill?.type !== 'AOE') {
                this.playImpact(event, vfx, target, groundZ, intensity);
                camera.addTrauma(0.2 * intensity); 
            } else {
                vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, target.z, event.skill?.color, groundZ);
            }
            return;
        }

        if (event.type === 'IMPACT_AOE') {
            // 強制對齊地面 + 4px 抬升解決 Z-fighting
            const impactPoint = { x: event.pos.x, y: event.pos.y, z: groundZ + 4 };
            this.playImpact(event, vfx, impactPoint, groundZ, intensity * 1.2);
            camera.addTrauma(0.35 * intensity);
            return;
        }
    }

    private static playImpact(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number, scale: number = 1.0) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // 1. 基礎命中粒子
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);

        // 2. TA 額外加成：重擊閃光
        if (scale > 1.8) {
            const flash = vfx.state.getParticle();
            flash.type = 'GLOW';
            flash.x = target.x; flash.y = target.y; flash.z = target.z;
            flash.size = 120 * scale;
            flash.color = '#ffffff';
            flash.life = 0.08; flash.maxLife = 0.08;
            flash.blendMode = 'lighter';
            vfx.state.particles.push(flash);
        }

        // 3. 散射碎片 (如果非持續性傷害)
        if (event.skill?.ccType !== 'DOT') {
            const count = Math.floor(3 * scale);
            for(let i=0; i<count; i++) {
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z;
                p.type = 'CHIP';
                p.color = color;
                p.size = 2 + Math.random() * 4;
                const angle = Math.random() * Math.PI * 2;
                const force = 150 + Math.random() * 300;
                p.vx = Math.cos(angle) * force;
                p.vy = Math.sin(angle) * force;
                p.vz = 200 + Math.random() * 400;
                p.gravity = 3000;
                p.life = 0.4 + Math.random() * 0.4;
                p.maxLife = p.life;
                vfx.state.particles.push(p);
            }
        }
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../../game";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../../../math/VisualMath";
import { UnitShatter } from "../effects/UnitShatter";

export class UnitVFXHandler {

    public static handle(event: GameEvent, engine: GameEngine, vfx: VFXSystem, camera: CameraSystem, origin: Point3D, groundZ: number) {

        if (event.type === 'DEATH') {
            const dAgent = engine.agents.find(a => a.id === event.sourceId);
            if (dAgent) {
                UnitShatter.spawn(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
            }
            camera.addTrauma(0.1);
            return;
        }

        if (event.type === 'SPAWN') {
            vfx.playEffect('FX_TELEPORT', origin.x, origin.y, groundZ, event.color, groundZ);
            return;
        }

        if (event.type === 'CAST_BREAK') {
            // 進度加成：詠唱越接近完成，爆炸效果越大 (0.5 ~ 1.5 倍)
            const progress = event.value || 0.1;
            const powerScale = 0.5 + progress;

            // 播放中斷碎裂特效
            vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);

            // 奧義被斷的懲罰性視覺反饋
            if (event.skill && event.skill.tag === 'ULT') {
                camera.addTrauma(0.5 * powerScale);
                // 額外的全場閃光 (White Wash)
                vfx.playEffect('FX_HIT_GENERIC', origin.x, origin.y, origin.z, '#ffffff');
            } else {
                camera.addTrauma(0.2 * powerScale); 
            }
            return;
        }
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../../game";
import { VFXSystem } from "../../vfx";
import { Point3D } from "../../../math/VisualMath";
import { SequenceSystem } from "../SequenceSystem";
import { SKILL_SEQUENCES } from "../../../../data/vfx/SkillSequences";

export class CinematicVFXHandler {

    public static handle(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        origin: Point3D, 
        target: Point3D
    ) {
        const skill = event.skill;
        if (!skill) return;

        // 1. DATA-DRIVEN ECS LOOKUP
        const sequence = SKILL_SEQUENCES[skill.id];

        if (sequence) {
            SequenceSystem.run(sequence, target, engine, vfx, event.sourceId);
            return;
        }

        // 2. MINIMAL FALLBACK (Prevents breaking if data entry is missing)
        if (event.type === 'VISUAL_SLASH') {
            vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
        } else {
            vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
        }
    }
}

import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { Point3D } from "../../math/VisualMath";
import { VFXSequence, VFXAction } from "../../../types/VFXSchema";
import { VisualMath } from "../../math/VisualMath";

interface QueuedAction {
    executeAt: number;
    action: VFXAction;
    target: Point3D;
    source?: Point3D;
}

export class SequenceSystem {
    private static actionQueue: QueuedAction[] = [];

    public static clear() {
        this.actionQueue = [];
    }

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        let sourcePos: Point3D | undefined;
        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) sourcePos = VisualMath.getUnitAnchor(agent, engine);
        }

        const baseTime = engine.battleTime;
        sequence.actions.forEach(action => {
            const executeAt = baseTime + (action.delay || 0);
            if (executeAt <= baseTime) {
                this.dispatch(action, target, sourcePos, vfx, engine);
            } else {
                this.actionQueue.push({ executeAt, action, target, source: sourcePos });
            }
        });
    }

    public static update(engine: GameEngine, vfx: VFXSystem) {
        const now = engine.battleTime;
        for (let i = this.actionQueue.length - 1; i >= 0; i--) {
            const item = this.actionQueue[i];
            if (now >= item.executeAt) {
                this.dispatch(item.action, item.target, item.source, vfx, engine);
                this.actionQueue.splice(i, 1);
            }
        }
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        const effectId = action.id || 'FX_HIT_GENERIC';
        const groundZ = target.z - 2; 

        switch (action.type) {
            case 'PARTICLE':
                vfx.playEffect(effectId, target.x, target.y, target.z, action.color, groundZ);
                break;
            case 'BEAM':
                if (source) vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                break;
            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.3);
                break;
            case 'GRID_PULSE':
                vfx.playEffect(action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', target.x, target.y, groundZ + 4, action.color, groundZ);
                break;
            case 'HEAVEN_FALL':
                const h = action.height || 1200;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;
                p.vz = -3500;
                p.life = (h / 3500) + 0.1; 
                p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1.8) * 80;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.locked = false;
                (p as any).pIsUlt = true; 
                vfx.state.particles.push(p);
                break;
        }
    }
}

import { Agent, GameEngine } from "../game";
import type { GridSystem } from "../systems/grid";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    /**
     * 計算場景轉場導致的垂直偏置 (SSOT Logic)
     */
    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    /**
     * Helper for entity-based HUD/VFX positioning.
     * Combines logical Y, terrain height, and physical offsets.
     */
    public static getEntityVisualY(logicalY: number, terrainH: number, physY: number, physZ: number, extraOffset: number = 0): number {
        const surfaceY = (logicalY + physY) - terrainH;
        return this.getIsoVisualY(surfaceY, physZ, extraOffset);
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number = 0): number {
        const bodyCenterY = this.getVisualBodyCenterY(surfaceY, z);
        return bodyCenterY - VISUAL_ANCHORS.HEAD_OFFSET_Y - 10 + bob;
    }

    public static applyLayerBias(visualY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return visualY - this.Z_LAYERS[layer];
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        // Corrected variable reference from agentId to targetId
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const p = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                return { x: p.x, y: p.y, z: h + 2 };
            }
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Point } from "../../types";
import { Point3D } from "./VisualMath";

export { Point3D };

/**
 * 飛行幾何真理庫 v14.0 - Analytic Ballistics
 */
export const TrajectoryMath = {

    /**
     * 線性插值座標 (解析解)
     */
    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    /**
     * 解析拋物線 (Parabolic Arc)
     * 計算在進度 t 時的 3D 座標，h 為頂點拱高
     */
    parabolic: (start: Point3D, end: Point3D, t: number, h: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;
        const linearZ = start.z * (1 - t) + end.z * t;
        // 拋物線高度公式: 4h * t * (1-t)
        const arcZ = 4 * h * t * (1 - t);
        return { x, y, z: linearZ + arcZ };
    },

    /**
     * 螺旋擺動軌跡 (Wobble Path)
     */
    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 1) return base;

        // 計算垂直於運動方向的法線向量
        const nx = -dy / dist;
        const ny = dx / dist;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z + Math.cos(t * Math.PI * 2 * freq) * amp * 0.5
        };
    },

    /**
     * 計算解析解在一階導數下的切向角
     * 會考慮 Z 軸變化對等角投影 (Y 軸壓縮) 的視覺影響
     */
    getProjectedAngle: (func: (t: number) => Point3D, t: number, isoScaleY: number): number => {
        const eps = 0.01;
        const p1 = func(t);
        const p2 = func(Math.min(1.0, t + eps));

        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;
        const dz = p2.z - p1.z;

        // 視覺 Y 變化量 = (物理 Y * ISO 壓縮) - 高度變化 Z
        const vy = dy * isoScaleY - dz;
        return Math.atan2(vy, dx);
    }
};

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";
import { Point3D } from "../math/VisualMath";

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();
    public reset() { this.state.reset(); }
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x; p.ty = end.y; p.tz = end.z;
        p.x = start.x; p.y = start.y; p.z = start.z;
        p.life = duration; p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; p.style = styleId; p.locked = true;
        this.state.particles.push(p);
    }
    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;
        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];
            if (p.delay && p.delay > 0) { p.delay -= dt; continue; }
            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop(); count--; continue;
            }
            if (p.locked) { p.rotation += p.vRotation * dt; continue; }
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX, dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) p.life = 0; 
            }
            VFXPhysics.update(p, dt, getTerrainHeight);
        }
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }
        this.ambience.update(dt, ambientType, this.state);
    }
}

import { GameEngine } from "../../../game";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath, Point3D } from "../../../math/VisualMath";
import { ISO_SCALE_Y } from "../../../../constants";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const def: ProjectileVisualDef = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'] || DEFAULT_PROJECTILE;

            const startP: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
            const endP: Point3D = { x: p.endX, y: p.endY, z: p.endZ };

            const getPosAt = (progress: number) => {
                if (def.trajectory === 'ARC') {
                    const arcH = Math.min(def.arcHeight || 150, Math.max(30, p.totalDist * 0.35));
                    return TrajectoryMath.parabolic(startP, endP, progress, arcH);
                }
                if (def.trajectory === 'WOBBLE') return TrajectoryMath.wobble(startP, endP, progress, def.wobbleAmp || 15, def.wobbleFreq || 2);
                return TrajectoryMath.linear(startP, endP, progress);
            };

            const current3D = getPosAt(p.t);
            // 核心修正：傳入正確的 ISO 縮放比例以修正旋轉角度
            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, p.t, ISO_SCALE_Y);

            const transOffset = VisualMath.getTransitionOffset(current3D.x, current3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visY = VisualMath.getIsoVisualY(current3D.y, current3D.z) + transOffset;

            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = current3D.y; 
            op.z = 5000 + current3D.z; 

            op.pVisX = current3D.x;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = def.spinSpeed ? (p.t * p.totalDuration * def.spinSpeed) : 0;
            op.pScale = def.scale || 1.0; 

            op.pTrail = [];
            const trailSamples = def.trailLength || 0;
            if (trailSamples > 0) {
                const step = 0.015; 
                for (let j = 1; j <= trailSamples; j++) {
                    const tPast = Math.max(0, p.t - j * step);
                    const past3D = getPosAt(tPast);
                    const pOffset = VisualMath.getTransitionOffset(past3D.x, past3D.y, engine.mapConfig, transitionT, transitionPhase);
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + pOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

