import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { BTNode, Selector, Sequence, Condition, Action } from "../behaviorTree";
import { STANDARD_AI_PROFILE, BTDef } from "../../data/ai_profiles";
import { BTConditions, BTActions } from "../ai/BTRegistry";
import { NodeState } from "../../types";

export class AISystem {

    // The new entry point using the Data-Driven Builder
    public buildAI(a: Agent, engine: GameEngine): BTNode {
        // In the future, we can load different profiles based on Agent Role
        // e.g. const profile = AI_DB[a.role] || STANDARD_AI_PROFILE;
        return this.parseNode(STANDARD_AI_PROFILE, engine);
    }

    private parseNode(def: BTDef, engine: GameEngine): BTNode {
        let node: BTNode;

        switch (def.type) {
            case 'SELECTOR':
                node = new Selector(def.name);
                if (def.children) {
                    def.children.forEach(childDef => {
                        node.add(this.parseNode(childDef, engine));
                    });
                }
                break;

            case 'SEQUENCE':
                node = new Sequence(def.name);
                if (def.children) {
                    def.children.forEach(childDef => {
                        node.add(this.parseNode(childDef, engine));
                    });
                }
                break;

            case 'CONDITION':
                const condFn = def.key ? BTConditions[def.key] : null;
                if (!condFn) {
                    console.warn(`AI Builder: Missing Condition Key '${def.key}'`);
                    // Fallback to avoid crash
                    node = new Condition(def.name, () => false); 
                } else {
                    node = new Condition(def.name, (agent: Agent) => condFn(agent, engine, def.args));
                }
                break;

            case 'ACTION':
                const actFn = def.key ? BTActions[def.key] : null;
                if (!actFn) {
                    console.warn(`AI Builder: Missing Action Key '${def.key}'`);
                    // Fallback
                    node = new Action(def.name, () => NodeState.FAILURE); // Failure
                } else {
                    node = new Action(def.name, (agent: Agent) => actFn(agent, engine, def.args));
                }
                break;

            default:
                throw new Error(`Unknown BT Node Type: ${(def as any).type}`);
        }

        return node;
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { Projectile, Skill, NodeState, AnimState } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { CastingEngine } from "./combat/CastingEngine";
import { SkillExecutor } from "./combat/SkillExecutor";
import { HexUtils } from "../utils";
export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public castingEngine: CastingEngine;
    public skillExecutor: SkillExecutor;
    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.castingEngine = new CastingEngine();
        this.skillExecutor = new SkillExecutor();
    }
    public reset() {
        // Projectiles are cleared by the GameEngine root container
    }
    public initiateCast(a: Agent, skillIdx: number, engine: GameEngine): NodeState {
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;
        if (isHardCC) return NodeState.FAILURE;
        const skill = a.skills[skillIdx];
        if (!skill) return NodeState.FAILURE;
        if (a.silenceTimer > 0 && skill.tag !== 'BASIC') return NodeState.FAILURE;
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = skillIdx;
            a.castTimer = skill.cast;
            a.castingAnimationTimer = skill.cast;
            a.btStatus = `詠唱 ${skill.tag}`;
            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;
            engine.log(a, 'CAST', '詠唱', targetName, `開始引導 ${skill.name} (需 ${skill.cast} 秒)`);
            // sourceId 必須傳遞，供 HUD 綁定文字
            engine.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: skill });
            a.setAnim(AnimState.ATTACK);
            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }
    public update(dt: number, engine: GameEngine) {
        engine.agents.forEach(a => {
            // 修正：如果單位已死但仍在詠唱，允許進入 updateCasting 進行中斷處理
            if (a.hp <= 0 && a.castingSkillIdx === -1) return;

            if (a.castingSkillIdx !== -1) {
                this.castingEngine.updateCasting(a, dt, engine, (agent) => {
                    this.completeCast(agent, engine);
                });
            }
        });
        this.projectileSystem.update(dt, engine, this.skillExecutor);
    }
    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             this.spawnProjectile(a, s, engine);
        } else {
            this.skillExecutor.executeInstantSkill(a, s, engine);
        }
    }
    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { HexUtils } from "../utils";
import { AnimState, Hex, NodeState } from "../../types";
import { Pathfinder } from "../ai/Pathfinder";
import { TargetingSystem } from "../ai/TargetingSystem";
import { MotionEngine } from "./movement/MotionEngine";
import { StackingResolver } from "./movement/StackingResolver";

export class MovementSystem {
    public pathfinder: Pathfinder;
    public targeting: TargetingSystem;
    private stackingResolver: StackingResolver;

    constructor() {
        this.pathfinder = new Pathfinder();
        this.targeting = new TargetingSystem();
        this.stackingResolver = new StackingResolver();
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        return this.targeting.getEffectiveRange(a, targetQ, targetR, baseRange, engine);
    }

    public updateTarget(a: Agent, engine: GameEngine) {
        this.targeting.updateTarget(a, engine);
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine) {
        return this.targeting.calculateOptimalTarget(source, skill, engine);
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        MotionEngine.updateMovement(a, dt, engine);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        const effRange = this.targeting.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        const distToTarget = HexUtils.dist(a, targetHex);

        // 1. 如果已經在射程內，停止移動並返回成功
        if (distToTarget <= effRange) {
            if (a.isMoving) {
                a.isMoving = false;
                a.path = [];
            }
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 2. 如果正在移動，檢查目的地是否需要更新
        if (a.isMoving && a.path.length > 0) {
            const currentGoal = a.path[a.path.length - 1];
            // 如果目標點沒變，繼續執行當前移動
            if (currentGoal.q === targetHex.q && currentGoal.r === targetHex.r) {
                a.moveSpeedMult = speedMult;
                return NodeState.RUNNING;
            }
            // 目標點變了，不中斷當前物理位移，但在下一個 Tick 重新計算路徑
        }

        // 3. 尋找新路徑
        let path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, false, engine, this.targeting);
        if (path.length === 0 && distToTarget > effRange) {
            // 如果被單位堵住，嘗試無視單位尋路（擠過去）
            path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, true, engine, this.targeting);
        }

        if (path.length > 0) {
            const next = path[0];
            // 檢查下一格是否被地形完全阻擋
            if (engine.isBlocked(next.q, next.r, a.id, a.movementType)) {
                a.setAnim(AnimState.COMBAT_IDLE);
                return NodeState.RUNNING;
            }

            // 更新路徑，保留移動狀態
            a.path = path;
            a.trajectory = path;
            if (!a.isMoving) {
                a.isMoving = true;
                a.moveProgress = 0;
            }
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this.stackingResolver.resolve(engine);
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { HexUtils } from "../utils";
import { MovementType, GroundHazard } from "../../types";
import { MapGenerator } from "./map/MapGenerator";
import { MapSpatial } from "./map/MapSpatial";
export class MapSystem {
    public agentMap: Map<number, Agent> = new Map();
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();
    public obstacles: Map<string, string> = new Map();
    public obstaclesHash: Set<number> = new Set();
    public heightMap: Map<string, number> = new Map();
    constructor() {}
    public registerAgent(agent: Agent) {
        const hash = HexUtils.hash(agent.q, agent.r);
        this.agentMap.set(hash, agent);
    }
    public unregisterAgent(agent: Agent) {
        const hash = HexUtils.hash(agent.q, agent.r);
        if (this.agentMap.get(hash) === agent) {
            this.agentMap.delete(hash);
        }
    }
    public removeAgentAt(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        this.agentMap.delete(hash);
    }
    public getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }
    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        const oldH = this.getTerrainHeight(agent.q, agent.r);
        const newH = this.getTerrainHeight(newQ, newR);
        const deltaH = oldH - newH;
        agent.physics.z += deltaH;
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }
    public clearAgents() {
        this.agentMap.clear();
    }
    public getTerrainHeight(q: number, r: number): number { return this.heightMap.get(HexUtils.key({q, r})) || 0; }
    public getHeightByKey(key: string): number { return this.heightMap.get(key) || 0; }
    public getMapKeys(): Set<string> { return this.mapKeys; }
    public isValid(q: number, r: number) { return this.validHashes.has(HexUtils.hash(q, r)); }
    public isValidHash(h: number) { return this.validHashes.has(h); }
    public resetData() {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this.heightMap.clear();
    }
    public registerTile(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.mapKeys.add(k);
        this.validHashes.add(h);
    }
    public removeTile(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.validHashes.delete(h);
        this.mapKeys.delete(k);
        this.heightMap.delete(k);
        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }
    public setHeight(key: string, height: number) { this.heightMap.set(key, height); }
    public setObstacle(q: number, r: number, type: string) {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.set(k, type);
        this.obstaclesHash.add(h);
    }
    public removeObstacle(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }
    public toggleObstacle(q: number, r: number, engine: GameEngine, type: string = 'WALL') {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!this.getAgentAt(q, r)) {
                this.obstacles.set(k, type);
                this.obstaclesHash.add(h);
            }
        }
    }
    public randomizeEnvironment(engine: GameEngine) { MapGenerator.randomize(this, engine); }
    public rebuildMap(engine: GameEngine) { MapGenerator.rebuild(this, engine); }
    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null, movementType: MovementType = MovementType.GROUND): boolean {
        return MapSpatial.isBlocked(this, q, r, engine, ignoreId, movementType);
    }
    public hasObstacle(q: number, r: number): boolean {
        return MapSpatial.hasObstacle(this, q, r);
    }
    public hasObstacleHash(h: number): boolean {
        return this.obstaclesHash.has(h);
    }
    // Corrected to use Map.get with generated key
    public getHazardAt(q: number, r: number, engine: GameEngine): GroundHazard | undefined {
        return engine.hazards.get(HexUtils.key({ q, r }));
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";

export class AgentManager {
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number, roleOverride?: Role): Agent | null {
        // Prevent spawning on blocked tiles or other units
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // 如果傳入了 roleOverride，則使用指定的職業，否則隨機分配
        if (roleOverride) {
            a.role = roleOverride;
        } else {
            const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
            a.role = allRoles[Math.floor(Math.random() * allRoles.length)];
        }

        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.spawnTimer = 0.5;
        engine.events.push({ type: 'SPAWN', pos: { x: a.px, y: a.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            a.animState = AnimState.IDLE;
        }

        engine.agents.push(a);
        engine.map.registerAgent(a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.px, y: a.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            // Remove from spatial map so others can walk here
            engine.map.unregisterAgent(a);

            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";
import { HEX_SIZE } from "../../../constants";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            const dtStep = dt / p.totalDuration;
            p.t = Math.min(1.0, p.t + dtStep);

            // 邏輯坐標插值 (作為物理真理)
            p.x = p.startX + (p.endX - p.startX) * p.t;
            p.y = p.startY + (p.endY - p.startY) * p.t;
            p.z = p.startZ + (p.endZ - p.startZ) * p.t;

            if (p.t >= 1.0) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = { x: p.endX, y: p.endY };

        if (p.skill.type === 'AOE') {
            const radiusGrid = p.skill.aoeRadius || 1;
            // 轉換為像素半徑，並給予微量寬容度 (+10px) 以補償視覺邊緣
            const radiusPx = radiusGrid * HEX_SIZE + 10;
            const radiusSq = radiusPx * radiusPx;

            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);

            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    // [FIX] 使用像素距離判定而非網格距離，解決視覺覆蓋但邏輯判失誤的問題
                    // 特別是對於核彈這種超大範圍、低速落點的技能
                    const targetPx = HexUtils.toPx(t.q, t.r, engine.mapConfig);
                    const dx = targetPx.x - hitPos.x;
                    const dy = targetPx.y - hitPos.y;
                    const distSq = dx*dx + dy*dy;

                    if (distSq <= radiusSq) {
                        // 即使施法者已死，只要 projectile 存在就應該造成傷害
                        // 如果 source 消失 (極端情況)，則無法計算屬性加成，暫時跳過
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });

            // 仍然生成危險區域 (Hazards 依賴網格)
            if (source) HazardManager.spawnHazards(source, HexUtils.range(hitHex, radiusGrid), p.skill, engine);

            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        const targetPoint = VisualMath.resolveTargetPoint(targetId, engine);

        const dx = targetPoint.x - launchPoint.x;
        const dy = targetPoint.y - launchPoint.y;
        const totalDist = Math.sqrt(dx*dx + dy*dy);
        const speed = skill.projectileSpeed || 800;

        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true;
        p.id = Math.random().toString(36).substr(2, 6);
        p.sourceId = source.id;
        p.team = source.team;
        p.skill = skill;
        p.t = 0;
        p.totalDuration = Math.max(0.1, totalDist / speed);
        p.startX = launchPoint.x; p.startY = launchPoint.y; p.startZ = launchPoint.z;
        p.endX = targetPoint.x; p.endY = targetPoint.y; p.endZ = targetPoint.z;
        p.totalDist = totalDist;
        p.targetId = targetId;
        p.trail = [];

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill, targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }

    private createEmptyProjectile(): Projectile {
        return { 
            id: '', active: false, createdAt: 0, lifespan: 0, 
            x: 0, y: 0, z: 0, t: 0, totalDuration: 0,
            startX: 0, startY: 0, startZ: 0, endX: 0, endY: 0, endZ: 0, totalDist: 0,
            targetId: '', targetPos: {x: 0, y: 0}, 
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [] 
        };
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";
import { COMBAT_PARAM } from "../../../constants";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });
            HazardManager.spawnHazards(source, impactCells, skill, engine);
        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);
        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "MISS", color: "#94a3b8" });
            engine.log(source, 'HIT', '未命中', target.id, `${skill.name} 被閃避`);
            return;
        }

        const oldHp = Math.ceil(target.hp);
        if (result.shieldAbsorb > 0) target.shield -= result.shieldAbsorb;

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
            engine.log(source, 'HEAL', '吸血', '自身', `獲得治療 ${result.vampAmount}`);
        }

        const isDamage = result.finalValue < 0;
        const absVal = Math.abs(result.finalValue);

        if (isDamage) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = COMBAT_PARAM.HIT_FLASH_DURATION;
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.min(600, 100 + absVal * 1.5);
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.4);

            engine.log(source, 'HIT', '命中', target.id, `${skill.name} 造成 ${absVal} 傷害${result.isCrit ? ' (暴擊!)' : ''}`);
        } else {
            engine.log(source, 'HEAL', '治療', target.id, `${skill.name} 恢復 ${absVal} 生命`);
        }

        engine.events.push({
            type: isDamage ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        if (oldHp > 0 && target.hp <= 0) {
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { MovementType } from "../../../types";

const STACKING_RESOLUTION_FORCE = 8;
const TRAIL_HISTORY_LENGTH = 15;
const FACING_THRESHOLD = 1.5; 

export class MotionEngine {

    public static updateMovement(a: Agent, dt: number, engine: GameEngine) {
        if (a.path.length === 0) {
            a.isMoving = false;
            a.moveProgress = 0;
            return;
        }

        const moveDelta = a.moveSpeed * a.moveSpeedMult * dt;
        a.moveProgress += moveDelta;

        const startH = { q: a.q, r: a.r };
        const nextHex = a.path[0];

        const c = HexUtils.toPx(startH.q, startH.r, engine.mapConfig);
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        if (Math.abs(n.x - a.px) > FACING_THRESHOLD) {
            a.facing = n.x > a.px ? 1 : -1;
        }

        const t = Math.min(1.0, a.moveProgress);
        a.px = c.x + (n.x - c.x) * t;
        a.py = c.y + (n.y - c.y) * t;

        if (a.movementType === MovementType.FLYING && a.hp > 0) {
            a.trailHistory.push({ x: a.px, y: a.py, z: a.physics.z });
            if (a.trailHistory.length > TRAIL_HISTORY_LENGTH) a.trailHistory.shift();
        }

        if (a.moveProgress >= 1.0) {
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);
            a.path.shift();

            if (a.path.length > 0) {
                a.moveProgress -= 1.0;
                this.updateMovement(a, 0, engine);
            } else {
                this.finalizeMove(a);
            }
        }
    }

    private static finalizeMove(a: Agent) {
        a.isMoving = false;
        a.moveSpeedMult = 1.0; 
        a.moveProgress = 0;

        a.physics.vx *= 0.1;
        a.physics.vy *= 0.1;

        a.physics.vx += (Math.random() - 0.5) * STACKING_RESOLUTION_FORCE;
        a.physics.vy += (Math.random() - 0.5) * STACKING_RESOLUTION_FORCE;
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { HexUtils, Vector } from "../../utils";
import { MovementType } from "../../../types";
import { BLOCK_HEIGHT } from "../../../constants";

/**
 * Robust Anti-Stacking System
 * Resolves accidental overlaps (from skills/physics) by expelling units to valid neighbors.
 */
export class StackingResolver {

    public resolve(engine: GameEngine) {
        const cellMap = new Map<number, Agent[]>();

        // 1. Group by logical coordinates
        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;
            const h = HexUtils.hash(a.q, a.r);
            if (!cellMap.has(h)) cellMap.set(h, []);
            cellMap.get(h)!.push(a);
        }

        // 2. Resolve multi-unit cells
        cellMap.forEach((occupants, hash) => {
            if (occupants.length > 1) {
                this.expelExcess(occupants, hash, engine);
            }
        });
    }

    private expelExcess(list: Agent[], hash: number, engine: GameEngine) {
        // Sort: Stationary units are "owners", moving units are "guests"
        list.sort((a, b) => (a.isMoving ? 1 : 0) - (b.isMoving ? 0 : 1));

        const owner = list[0];
        const currentH = engine.map.getTerrainHeight(owner.q, owner.r);

        for (let i = 1; i < list.length; i++) {
            const guest = list[i];
            const found = this.findExpulsionSpot(guest, currentH, engine);

            if (found) {
                // Perform Logical Displacement
                engine.updateAgentPosition(guest, found.q, found.r);

                // Clear active move to prevent pathing glitches
                if (guest.isMoving) {
                    guest.isMoving = false;
                    guest.path = [];
                }

                // Add small physical impulse to separate visually
                const dir = Vector.normalize(Vector.sub(
                    HexUtils.toPx(found.q, found.r, engine.mapConfig), 
                    HexUtils.toPx(owner.q, owner.r, engine.mapConfig)
                ));
                guest.physics.vx += dir.x * 200;
                guest.physics.vy += dir.y * 200;

                engine.log(guest, 'SYSTEM', '擠出', `從 (${owner.q},${owner.r})`, '解決重疊狀態');
            }
        }
    }

    private findExpulsionSpot(agent: Agent, sourceH: number, engine: GameEngine) {
        // Spiral-like search: Check nearest neighbors first
        const neighbors = HexUtils.neighbors(agent);

        // Shuffle to avoid directional bias
        for (let i = neighbors.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
        }

        for (const n of neighbors) {
            // Check basic validity
            if (!engine.map.isValid(n.q, n.r)) continue;

            // Check if already blocked by static or dynamic
            if (engine.map.isBlocked(n.q, n.r, engine, agent.id)) continue;

            // Height Safety Check - Modified for "Jump Down"
            if (agent.movementType === MovementType.GROUND) {
                const nH = engine.map.getTerrainHeight(n.q, n.r);
                const deltaH = nH - sourceH;
                const jumpLimit = Math.max(1, agent.jump) * BLOCK_HEIGHT;

                // Block if trying to climb UP too high
                if (deltaH > jumpLimit) continue;

                // Allow falling down regardless of height (pushed off cliff)
            }

            return n;
        }
        return null;
    }
}

import type { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { MovementType } from "../../../types";
import { OBSTACLE_DB } from "../../../data/obstacles";
import { MapSystem } from "../map";

export class MapSpatial {

    public static isBlocked(
        system: MapSystem,
        q: number, 
        r: number, 
        engine: GameEngine, 
        ignoreId: string | null = null, 
        movementType: MovementType = MovementType.GROUND
    ): boolean {
        const h = HexUtils.hash(q, r);

        // 1. Static Obstacles
        if (system.obstaclesHash.has(h)) {
            const obsId = system.obstacles.get(HexUtils.key({q, r}));
            const def = obsId ? OBSTACLE_DB[obsId] : null;
            if (movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) return true;
        }

        // 2. Dynamic Units (Already Standing There)
        const occupant = engine.agentMap.get(h);
        if (occupant && occupant.id !== ignoreId && occupant.hp > 0 && !occupant.banished) return true;

        // 3. Movement Intent (Strict Reservation)
        // Check if any other agent is moving TO this cell
        for (const a of engine.agents) {
            if (a.id === ignoreId || a.hp <= 0 || !a.isMoving || a.path.length === 0) continue;
            const dest = a.path[0];
            if (dest.q === q && dest.r === r) return true;
        }

        return false;
    }

    public static hasObstacle(system: MapSystem, q: number, r: number): boolean {
        return system.obstaclesHash.has(HexUtils.hash(q, r));
    }
}

import type { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = Math.floor((W - 1) / 2);
        const centerR = Math.floor((H - 1) / 2);
        const centerHex = { q: centerQ, r: centerR };

        // 用於計算前景深度的參考值
        const centerSum = centerQ + centerR;

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                let rawVal = (Math.sin((q + noisePhaseA) * 0.45) + Math.cos((r + noisePhaseB) * 0.45)) * 3.5;

                // Steeper bowl edges
                rawVal += (dist * 0.8); 

                // 視覺修正：前景壓低 (防止遮擋戰場視線)
                const visualDepth = (q + r) - centerSum;
                if (visualDepth > 0) {
                    rawVal -= (visualDepth * 0.8); 
                    if (dist > 3) rawVal -= (dist * 0.3);
                }

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerHex = { q: Math.floor(W/2), r: Math.floor(H/2) };
        const keys = Array.from(system.getMapKeys());

        // Tuned Density per Biome
        let density = 0.3;
        let noiseThreshold = 0.4;

        if (engine.currentScene.textureType === 'FOREST') {
            density = 0.45; // Denser Forest
            noiseThreshold = 0.2; // Clumpier
        } else if (engine.currentScene.textureType === 'DESERT') {
            density = 0.4; // Scattered Rocks
            noiseThreshold = 0.3;
        }

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            // Leave center clear for fighting
            if (dist < 2.5) return; 

            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > noiseThreshold && Math.random() < density) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {
    /**
     * 計算有效射程（考慮高地加成）
     */
    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);
        const deltaH = h1 - h2;
        const heightBonus = deltaH > 0 ? Math.floor(deltaH / BLOCK_HEIGHT * 0.5) : 0;
        return baseRange + heightBonus;
    }

    /**
     * RTS 等級目標選取評分 - V2.0 修正版
     * 解決「近身不打、跑去打遠處法師」的問題
     */
    public updateTarget(a: Agent, engine: GameEngine) {
        // 如果當前目標已經死亡或無效，先清除
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let maxScore = -Infinity;
        let bestTarget: Agent | null = null;

        // 如果被嘲諷，強制鎖定嘲諷來源
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const taunter = engine.agents.find(ag => ag.id === a.tauntTargetId);
            if (taunter && taunter.hp > 0 && !taunter.banished) {
                a.target = taunter;
                return;
            }
        }

        const isSilenced = a.silenceTimer > 0;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = Math.max(0.5, HexUtils.dist(a, o));

                // 1. 距離權重 (Exponential Falloff)
                // 修正：極大幅度提高近距離權重
                const distScore = 2000 / (dist + 0.5); 

                // 2. 血量權重 (殘血優先)
                const hpScore = (1 - o.hp / o.maxHp) * 50;

                // 3. 威脅權重 (Threat)
                let threatScore = 0;
                if (!isSilenced && o.castingSkillIdx !== -1) {
                    const castingSkill = o.skills[o.castingSkillIdx];
                    if (castingSkill?.tag === 'ULT') {
                        threatScore = 200; 
                    } else if (castingSkill?.tag === 'ACTIVE') {
                        threatScore = 50; 
                    }
                }

                // 4. 黏著加分 (Hysteresis)
                // 如果是當前目標，給予加分以避免頻繁切換 (防抖)
                const stickyBonus = (a.target === o) ? 300 : 0;

                // 總分計算
                const score = distScore + hpScore + threatScore + stickyBonus;

                if (score > maxScore) {
                    maxScore = score;
                    bestTarget = o;
                }
            }
        }
        a.target = bestTarget;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // AOE 邏輯保持不變
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }

        // 單體技能優化：黏著邏輯
        // 如果當前目標有效且在射程內，直接鎖定，不要嘗試移動尋找「更好」的位置
        if (source.target && source.target.hp > 0 && !source.target.banished) {
            const effRange = this.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
            if (HexUtils.dist(source, source.target) <= effRange) {
                return { targetAgent: source.target, targetHex: null };
            }
        }

        // 如果沒有目標，或目標無效，或目標超出射程，才刷新
        this.updateTarget(source, engine);
        return { targetAgent: source.target, targetHex: null };
    }

    public getImpactArea(source: Agent, targetHex: Hex, skill: Skill, engine: GameEngine): Hex[] {
        if (skill.type === 'AOE') {
            const radius = skill.aoeRadius || 1;
            return HexUtils.range(targetHex, radius).filter(h => engine.map.isValid(h.q, h.r));
        }
        return [targetHex];
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const range = skill.range;
        const radius = skill.aoeRadius || 1;
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);

        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        let bestHex: Hex | null = null;
        let maxImpact = -1;

        const candidates = new Set<string>();
        enemies.forEach(e => {
            candidates.add(HexUtils.key(e));
            if (radius > 1) {
                HexUtils.neighbors(e).forEach(n => candidates.add(HexUtils.key(n)));
            }
        });

        candidates.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };
            if (!engine.map.isValid(q, r)) return;

            if (HexUtils.dist(source, targetHex) > this.getEffectiveRange(source, q, r, range, engine)) return;

            let impact = 0;
            enemies.forEach(e => {
                if (HexUtils.dist(targetHex, e) <= radius) {
                    const weight = (e.castingSkillIdx !== -1 && e.skills[e.castingSkillIdx]?.tag === 'ULT') ? 5.0 : 1.0;
                    impact += weight * (1.0 + (1 - e.hp/e.maxHp));
                }
            });

            if (impact > maxImpact) {
                maxImpact = impact;
                bestHex = targetHex;
            }
        });

        return { targetAgent: null, targetHex: bestHex };
    }
}

import { Agent } from "../core/Agent";
import type { GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

interface PQNode {
    hash: number;
    priority: number;
}

export class Pathfinder {
    private _gScore = new Map<number, number>();
    private _cameFrom = new Map<number, number>();
    private _pq: PQNode[] = [];

    public findPath(startAgent: Agent, endQ: number, endR: number, range: number, ignoreUnits: boolean, engine: GameEngine, targeting: TargetingSystem): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);
        const goalHex = { q: endQ, r: endR };

        // 射程檢查：若已在動態射程內，則無需移動
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        if (HexUtils.dist(startAgent, goalHex) <= effRange) return [];

        this._gScore.clear();
        this._cameFrom.clear();
        this._pq = [];

        this._gScore.set(startH, 0);
        this.pqPush(startH, 0);

        let iterations = 0;
        let bestH = -1;
        const MAX_ITER = 600; 

        while (this._pq.length > 0 && iterations < MAX_ITER) {
            iterations++;
            const current = this.pqPop()!;
            const currentHex = HexUtils.unhash(current.hash);

            // 成功判定：進入有效射程
            if (HexUtils.dist(currentHex, goalHex) <= targeting.getEffectiveRange(currentHex, endQ, endR, range, engine)) {
                bestH = current.hash;
                break;
            }

            for (let i = 0; i < 6; i++) {
                const neighborH = current.hash + NEIGHBOR_HASH_OFFSETS[i];
                if (!engine.map.isValidHash(neighborH)) continue;

                // 物理碰撞判定
                if (engine.map.hasObstacleHash(neighborH)) {
                    const type = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(neighborH)));
                    const def = OBSTACLE_DB[type || 'WALL'];
                    if (startAgent.movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) continue;
                }

                if (!ignoreUnits) {
                    const occ = engine.agentMap.get(neighborH);
                    if (occ && occ.hp > 0 && occ !== startAgent) continue;
                }

                // 數學地勢成本計算 (Asymmetric Verticality)
                const nHex = HexUtils.unhash(neighborH);
                let moveCost = 1.0;

                if (startAgent.movementType !== MovementType.FLYING) {
                    const h1 = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const h2 = engine.map.getTerrainHeight(nHex.q, nHex.r);

                    const deltaH = h2 - h1; // Target - Current
                    const jumpLimit = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                    // 1. 向上攀爬 (Climbing Up)：嚴格檢定
                    if (deltaH > jumpLimit) continue; 

                    // 2. 向下跳躍 (Jumping Down)：允許任何高度 (物理引擎會處理傷害)
                    // 無需檢查 deltaH < -jumpLimit

                    // Cost Calculation
                    if (deltaH > 0) {
                        // 上坡成本：隨高度增加
                        moveCost += deltaH / BLOCK_HEIGHT * 0.5; 
                    } else {
                        // 下坡/跳崖成本：固定小額成本 (不隨深度增加，否則 AI 會不敢跳崖)
                        // 給予微小懲罰讓 AI 優先選擇平地，但非阻斷性
                        moveCost += 0.2;
                    }
                }

                const tentativeG = (this._gScore.get(current.hash) || 0) + moveCost;

                if (!this._gScore.has(neighborH) || tentativeG < this._gScore.get(neighborH)!) {
                    this._cameFrom.set(neighborH, current.hash);
                    this._gScore.set(neighborH, tentativeG);

                    // 核心數學：六邊形 Cube 曼哈頓距離啟發函數
                    const hCost = HexUtils.dist(nHex, goalHex);
                    this.pqPush(neighborH, tentativeG + hCost);
                }
            }
        }

        return bestH !== -1 ? this.reconstructPath(bestH, startH) : [];
    }

    private pqPush(hash: number, priority: number) {
        this._pq.push({ hash, priority });
        // 生產環境應使用 Binary Heap，此處使用排序模擬
        this._pq.sort((a, b) => a.priority - b.priority); 
    }

    private pqPop() { return this._pq.shift(); }

    private reconstructPath(current: number, startH: number): Hex[] {
        const path: Hex[] = [];
        let curr = current;
        while (curr !== startH && path.length < 100) {
            path.push(HexUtils.unhash(curr));
            curr = this._cameFrom.get(curr) || -1;
        }
        return path.reverse();
    }
}

import type { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};
const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN', 'BLACK_HOLE'
]);
const FIXED_ORIENTATION_PARTICLES = new Set([
    'GRID_FIELD', 'PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX', 'BLACK_HOLE'
]);
const PROCEDURAL_TYPES = new Set([
    'PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE', 
    'DEATH_RAY', 'SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'BLACK_HOLE'
]);
export class VFXPlayer {
    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];
        if (!asset) return;
        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }
    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;
        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);
            if (config.shape === 'POINT') {} 
            else if (config.shape === 'BURST_DIR') {
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);
                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); 
            }
            else if (config.shape === 'CIRCLE') {
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;
                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }
            if (config.vz !== undefined) {
                vz = rnd(config.vz);
            }
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;
            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);
            p.size = rnd(config.size);
            if (config.height !== undefined) p.height = rnd(config.height);
            p.color = colorOverride || pickColor(config.colors);
            p.type = config.particleType as any;
            if (config.visualStyle) p.style = config.visualStyle;
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.gravity !== undefined) p.gravity = config.gravity;
            if (config.vRotation) {
                p.vRotation = rnd(config.vRotation);
            } else {
                p.vRotation = FIXED_ORIENTATION_PARTICLES.has(config.particleType) ? 0 : (Math.random() - 0.5) * 10;
            }
            if (config.blendMode) p.blendMode = config.blendMode;
            if (!p.image && !PROCEDURAL_TYPES.has(p.type)) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }
            system.state.particles.push(p);
        }
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "IsFeared": (a) => a.fearTimer > 0, 

    "HasTarget": (a, engine) => {
        // Update target logic:
        // 1. If we have a valid target, keep it unless taunted elsewhere
        if (a.target && a.target.hp > 0 && !a.target.banished) {
            if (a.tauntTimer > 0 && a.tauntTargetId !== a.target.id) {
                // Taunted to another person, force re-scan will happen below if we return false?
                // Actually updateTarget handles the switch logic.
            } else {
                return true; 
            }
        }

        // 2. Periodic Scan or No Target
        if (a.aiUpdateTimer <= 0 || !a.target || a.target.hp <= 0) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; 
        }

        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        // Robustness: Handle NaN
        let cd = a.curCDs[idx];
        if (isNaN(cd)) cd = 0;

        const tolerance = (s.tag === 'BASIC') ? 0.15 : 0.01;
        const isOnCD = cd > tolerance; 

        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            return true;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const gridDist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        // Robustness: Add 0.5 tolerance for floating point/physics drift when adjacent
        if (gridDist > effRange + 0.5) return false;

        // Pixel check for adjacency safety
        if (effRange <= 1.0) {
            const startPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            let endPx;
            if (a.targetHex) endPx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig);
            else endPx = { x: a.target!.px, y: a.target!.py };
            const dx = startPx.x - endPx.x;
            const dy = startPx.y - endPx.y;
            const pxDist = Math.sqrt(dx*dx + dy*dy);

            // Allow a bit more slack visually (2.8 tiles instead of 2.5)
            if (pxDist > HEX_SIZE * 2.8) return false;
        }

        return true;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        if (a.isMoving) {
            a.isMoving = false;
            a.path = [];
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        let dest = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);

        if (dest) {
            // Check if we are already there (redundant check but safe)
            if (a.q === dest.q && a.r === dest.r) return NodeState.SUCCESS;
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `追蹤 ${a.target.id}`;
        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

import { Agent } from "../../core/Agent";
import { Skill, Role } from "../../../types";
import { COMBAT_PARAM } from "../../../constants";

export interface DamageResult {
    finalValue: number;     // Final HP delta (negative for damage, positive for heal)
    shieldAbsorb: number;   // Amount absorbed by shield
    isCrit: boolean;        // Critical hit?
    isExecute: boolean;     // Execute trigger?
    isBlock: boolean;       // Tank block?
    isMiss: boolean;        // Blind miss?
    vampAmount: number;     // Lifesteal value
    manaBurn: number;       // MP burned
    manaRestore: number;    // MP restored
    overkill: number;       // Damage exceeding remaining HP
}

export class DamageCalculator {

    /**
     * The Core Damage Pipeline:
     * Hit Check (Blind) -> Base -> Multipliers -> Crit/Execute -> Mitigation (Shield/Def/Block) -> Final
     */
    public static calculate(source: Agent, target: Agent, skill: Skill): DamageResult {
        const isHeal = skill.power < 0;
        let base = Math.abs(skill.power);

        const result: DamageResult = {
            finalValue: 0,
            shieldAbsorb: 0,
            isCrit: false,
            isExecute: false,
            isBlock: false,
            isMiss: false,
            vampAmount: 0,
            manaBurn: 0,
            manaRestore: 0,
            overkill: 0
        };

        // 0. Miss Logic (Blind)
        if (!isHeal && source.blindTimer > 0) {
            // 50% Chance to miss if blinded
            if (Math.random() < 0.5) {
                result.isMiss = true;
                return result; // Early exit on miss
            }
        }

        // 1. Role Multipliers & Base Logic
        if (!isHeal) {
            // Ranger: Bonus dmg at max range? (Placeholder logic)
            // Mage: Bonus vs High Armor? 
        }

        // 2. Execute Logic (斬殺)
        const isExec1 = skill.effectType === 'EXECUTE';
        const isExec2 = skill.effectType2 === 'EXECUTE';

        if (!isHeal && (isExec1 || isExec2)) {
            const threshold = COMBAT_PARAM.EXECUTE_THRESHOLD;
            if (target.hp < target.maxHp * threshold) {
                const multiplier = (isExec1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_EXECUTE_MULTIPLIER;
                base *= multiplier;
                result.isExecute = true;
            }
        }

        // 3. Crit Logic
        if (!isHeal && Math.random() < 0.1) {
            base *= 1.5;
            result.isCrit = true;
        }

        // 4. Mitigation (Tank Block Logic)
        if (!isHeal && target.role === Role.TANK && target.hp > 0) {
            base *= 0.85; 
            result.isBlock = true;
        }

        // 5. Shield Absorption (NEW)
        let absorbed = 0;
        if (!isHeal && target.shield > 0) {
            absorbed = Math.min(target.shield, base);
            base -= absorbed;
            result.shieldAbsorb = absorbed;
        }

        // 6. Final Calculation
        let final = Math.floor(base);

        // 7. Secondary Effects (Vamp, Mana)
        const isVamp1 = skill.effectType === 'VAMP';
        const isVamp2 = skill.effectType2 === 'VAMP';
        if (!isHeal && (isVamp1 || isVamp2)) {
            const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_VAMP_PCT;
            // Vamp based on unmitigated damage or actual HP damage? Usually actual.
            result.vampAmount = Math.floor(final * vampPct);
        }

        // Mana Burn
        let mb = 0;
        if (skill.effectType === 'MANA_BURN') mb += (skill.effectVal || COMBAT_PARAM.MANA_BURN_DEFAULT);
        if (skill.effectType2 === 'MANA_BURN') mb += (skill.effectVal2 || COMBAT_PARAM.MANA_BURN_DEFAULT);
        result.manaBurn = mb;

        // Mana Restore
        let mr = 0;
        if (skill.effectType === 'MANA_RESTORE') mr += (skill.effectVal || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        if (skill.effectType2 === 'MANA_RESTORE') mr += (skill.effectVal2 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        result.manaRestore = mr;

        // 8. Apply Direction (Damage is negative)
        result.finalValue = isHeal ? final : -final;

        // 9. Overkill Calc
        if (!isHeal && final > target.hp) {
            result.overkill = final - target.hp;
        }

        return result;
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { Vector, HexUtils } from "../../utils";

export const CCManager = {

    // Unified Entry Point
    applyCC(
        source: Agent, 
        target: Agent, 
        skill: Skill, 
        type: string | undefined, 
        dur: number | undefined, 
        force: number | undefined, 
        origin: {x: number, y: number} | undefined, 
        engine: GameEngine
    ) {
        if (!type || type === 'NONE') return;

        // 1. DR Check
        const { effectiveDuration, isImmune } = this.checkDR(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫", color: "#9ca3af" });
            return;
        }

        let statusText = "";
        let statusColor = "#fff";

        // 2. Application Logic
        switch (type) {
            case 'STUN':
                // Extend duration logic
                if (effectiveDuration > target.stunTimer) {
                    target.stunTimer = effectiveDuration;
                    target.stunMax = effectiveDuration;
                }
                target.isMoving = false;
                // Don't override DEATH animation
                if (target.hp > 0) target.setAnim(AnimState.STUN);
                statusText = "暈眩"; statusColor = "#facc15";

                // Special Visuals
                if (skill.element === 'ICE') target.visualStatus = 'FROZEN';
                break;

            case 'SILENCE':
                if (effectiveDuration > target.silenceTimer) {
                    target.silenceTimer = effectiveDuration;
                    target.silenceMax = effectiveDuration;
                }
                statusText = "沉默"; statusColor = "#94a3b8";
                break;

            case 'BANISH':
                if (effectiveDuration > target.banishTimer) {
                    target.banishTimer = effectiveDuration;
                    target.banishMax = effectiveDuration;
                }
                target.banished = true;
                target.isMoving = false;
                if (target.hp > 0) target.setAnim(AnimState.STUN);

                statusText = "放逐"; statusColor = "#c084fc";

                // Model Swap
                if (skill.specialVisualStatus) target.visualStatus = skill.specialVisualStatus;
                break;

            case 'ROOT':
                if (effectiveDuration > target.rootTimer) target.rootTimer = effectiveDuration;
                target.isMoving = false;
                statusText = "禁錮"; statusColor = "#fbbf24";
                break;

            case 'FEAR':
                if (effectiveDuration > target.fearTimer) target.fearTimer = effectiveDuration;
                statusText = "恐懼"; statusColor = "#a855f7";
                break;

            case 'TAUNT':
                if (effectiveDuration > target.tauntTimer) {
                    target.tauntTimer = effectiveDuration;
                    target.tauntTargetId = source.id; 
                }
                statusText = "嘲諷"; statusColor = "#ef4444";
                break;

            case 'BLIND':
                if (effectiveDuration > target.blindTimer) target.blindTimer = effectiveDuration;
                statusText = "致盲"; statusColor = "#cbd5e1";
                break;

            case 'SHIELD':
                // Force = Shield Amount
                const amount = force || 50;
                target.shield += amount;
                target.maxShield = Math.max(target.maxShield, target.shield);
                statusText = "護盾"; statusColor = "#bae6fd";
                break;

            case 'KNOCKBACK':
            case 'PULL':
                const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
                if (result.applied) {
                    statusText = type === 'PULL' ? "牽引" : "擊退";
                    if (target.hp > 0) target.setAnim(AnimState.HIT);
                    target.physics.vz += 150; // Pop up slightly
                }
                break;

            case 'DOT':
                target.dotDmg = force || 10;
                target.dotTimer = effectiveDuration;
                statusText = "中毒"; statusColor = "#10b981";
                break;

            case 'HOT':
                target.hotVal = force || 10;
                target.hotTimer = effectiveDuration;
                statusText = "再生"; statusColor = "#86efac";
                break;
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
            engine.log(source, 'CC', type, target.id, `施加 ${statusText} (${effectiveDuration.toFixed(1)}s)`);
        }
    },

    checkDR(target: Agent, type: string, baseDuration: number) {
        const isHardCC = ['STUN', 'SILENCE', 'BANISH', 'FEAR', 'TAUNT', 'ROOT'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false };

        const stacks = target.drStacks[type] || 0;
        // Standard exponential decay: 100% -> 50% -> 25% -> 12.5% (Immune)
        const multiplier = Math.pow(0.5, stacks); 

        if (multiplier < 0.2) return { effectiveDuration: 0, isImmune: true };

        // Apply stack
        target.drStacks[type] = stacks + 1;
        target.drTimers[type] = 10.0; // Reset 10s window

        return { effectiveDuration: baseDuration * multiplier, isImmune: false };
    },

    calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        // Force = Number of tiles to push
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 

        const tilesToPush = Math.max(0, rawForce - resistance);
        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};

        // Vector from Origin to Target
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));

        // PULL inverts direction
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1); 

        let currentH = {q: target.q, r: target.r};
        let finalH = currentH;

        // Iterative Step-Checking (To handle collisions per tile)
        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN: any = null;
            let bestDot = -2.0; // Dot product range is -1 to 1

            // Find neighbor that best aligns with force vector
            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));

                const dot = nDir.x * vector.x + nDir.y * vector.y;
                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                // Collision Logic
                // 1. Map Valid
                if (!engine.map.isValid(bestN.q, bestN.r) || engine.map.hasObstacle(bestN.q, bestN.r)) break; 

                // 2. Unit Collision
                if (engine.getAgentAt(bestN.q, bestN.r)) break; 

                // 3. Cliff Check (Can't be knocked up a huge wall)
                const curHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > curHeight + 24) break; 

                // Success
                currentH = bestN;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            // Break any current move
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }
};

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { AnimState } from "../../../types";

export class CastingEngine {

    public updateCasting(a: Agent, dt: number, engine: GameEngine, onComplete: (a: Agent) => void) {
        // 1. 硬控場檢查 (Interrupt Priority)
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. 動態轉向 (Sticky Targeting)：確保攻擊動作始終朝向目標
        if (a.target) {
            const dx = a.target.px - a.px;
            if (Math.abs(dx) > 2) { // 避免高頻抖動
                a.facing = dx > 0 ? 1 : -1;
            }
        }

        // 3. 詠唱進度積分
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            onComplete(a);
            this.resetCaster(a);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                // 計算進度比：進度越高，中斷爆炸越強
                const progressPct = 1 - (a.castTimer / s.cast);

                engine.log(a, 'CC', '中斷', s.name, `詠唱被打斷 (進度: ${Math.floor(progressPct * 100)}%)`);

                // 傳遞精確的 3D 位置與進度參數，並補上 sourceId
                engine.events.push({ 
                    type: 'CAST_BREAK', 
                    pos: { x: a.px, y: a.py }, 
                    value: progressPct, // 這裡重用 value 傳遞進度
                    color: s.color, 
                    skill: s,
                    sourceId: a.id 
                });
            }
        }
        this.resetCaster(a);
        a.setAnim(AnimState.IDLE); 
    }

    private resetCaster(a: Agent) {
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }
}

