};

import { Agent } from "../../core/Agent";

export class CooldownSystem {
    public update(agent: Agent, dt: number) {
        // Skill Cooldowns
        for (let i = 0; i < agent.curCDs.length; i++) {
            if (agent.curCDs[i] > 0) {
                agent.curCDs[i] -= dt;
                // Safety Clamp: Prevent negative small floats or NaN
                if (agent.curCDs[i] < 0 || isNaN(agent.curCDs[i])) {
                    agent.curCDs[i] = 0;
                }
            }
        }

        // Spawn Animation Timer
        if (agent.spawnTimer > 0) {
            agent.spawnTimer -= dt;
            if (agent.spawnTimer < 0) agent.spawnTimer = 0;
        }
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";

export class EffectSystem {

    // Throttle visual numbers to avoid UI clutter
    private readonly FEEDBACK_INTERVAL = 0.5; 
    private feedbackTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        if (agent.hp <= 0 || agent.banished) return;

        const feedbackKey = agent.id;
        let timer = this.feedbackTimers.get(feedbackKey) || 0;
        timer -= dt;

        // 1. Damage over Time (DoT)
        // Mathematically apply damage per second
        if (agent.dotTimer > 0) {
            agent.dotTimer = Math.max(0, agent.dotTimer - dt);

            const damagePerSec = agent.dotDmg;
            let frameDamage = damagePerSec * dt;

            // Shield Mitigation logic (Standardized)
            if (agent.shield > 0) {
                const absorbed = Math.min(agent.shield, frameDamage);
                agent.shield -= absorbed;
                frameDamage -= absorbed;
            }

            if (frameDamage > 0) {
                agent.hp -= frameDamage;
            }

            // Periodic Visual Feedback
            if (timer <= 0 && agent.dotDmg > 0) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damagePerSec), 
                    color: '#10b981', // Poison Green default
                    skill: { ccType: 'DOT' } as any 
                });
                agent.hitFlashTimer = 0.1;
                // Don't reset timer yet, wait for HoT check
            }
        }

        // 2. Heal over Time (HoT)
        if (agent.hotTimer > 0) {
            agent.hotTimer = Math.max(0, agent.hotTimer - dt);

            const healPerSec = agent.hotVal;
            const frameHeal = healPerSec * dt;

            agent.hp = Math.min(agent.maxHp, agent.hp + frameHeal);

            // Periodic Visual Feedback
            if (timer <= 0 && agent.hotVal > 0) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.floor(healPerSec), 
                    color: '#86efac' 
                });
                // Reset timer now
                this.feedbackTimers.set(feedbackKey, this.FEEDBACK_INTERVAL);
            }
        } else {
            // Update timer if we didn't reset it
            if (timer <= 0) this.feedbackTimers.set(feedbackKey, this.FEEDBACK_INTERVAL);
            else this.feedbackTimers.set(feedbackKey, timer);
        }
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 0. AI Tick Update (System-wide clock for the agent)
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Jitter & Twitching
            // 使用 aiUpdateTimer 進行決策限流，防止每幀重新尋路導致的原地抽搐
            if (agent.rootTimer <= 0) {
                if (!agent.isMoving && agent.aiUpdateTimer <= 0) {
                    // 擴大搜索半徑至 4 格，模擬驚慌亂跑
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        // 排除近身 (Range < 2)，強迫跑遠
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        // 強制走到該點，速度 1.5x
                        const result = engine.moveAgentToHex(agent, targetHex, 0, 1.5);
                        if (result === 'R') { // RUNNING (Success)
                            agent.aiUpdateTimer = 0.5; // 決策冷卻：給予時間執行移動
                        } else {
                            agent.aiUpdateTimer = 0.8; // 失敗冷卻：避免高頻重試
                        }
                    } else {
                        agent.aiUpdateTimer = 0.8; // 無路可逃，等待
                    }
                }
            } else {
                agent.isMoving = false;
                agent.path = [];
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);

                // Lift particles up to chest/head height so they aren't hidden by the body
                // Agent Z is bottom of feet relative to terrain.
                // 45 is roughly center mass.
                const pz = agent.physics.z + 45;

                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('BURN', agent.dotTimer > 0 && agent.dotDmg > 0); // Explicitly check BURN
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { Agent } from "../../core/Agent";
import { MapConfig } from "../../utils";

export interface UnitVisualState {
    agent: Agent;
    x: number;
    y: number;
    z: number;
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number;
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {
    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {
        const isDead = agent.hp <= 0;
        const visualX = agent.px + agent.physics.x;
        const visualY = agent.py + agent.physics.y;

        // 核心：使用邏輯網格位置作為高度真理
        const terrainH = getTerrainHeight(agent.q, agent.r);
        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: agent.physics.z,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY: agent.py, 
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent } from "../../core/Agent";
import type { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";
import { VisualMath } from "../../math/VisualMath";

export class GridSpatial {
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexUtils.range({q: centerQ, r: centerR}, radius);
        return candidates.filter(hex => engine.map.isValid(hex.q, hex.r));
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        // 解算高度步進，匹配視覺投影
        const maxHeight = 300; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        for (let h = 0; h <= maxHeight; h += step) {
            // 修正：解算 Y 軸時應考慮 Z 的物理貢獻
            // 視覺投影 vy = y - z -> y = vy + z
            const testY = wy + h; 
            const rounded = HexUtils.fromPx(wx, testY, engine.mapConfig);
            const tile = cache.tileMap.get(HexUtils.key(rounded));

            if (tile) {
                const visualTopY = VisualMath.getIsoVisualY(tile.py, tile.h);
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            const currentSort = a.q + a.r;
            for (const n of neighbors) {
                // Topological occlusion check
                if ((n.q + n.r) > currentSort) {
                    if (engine.mapKeys.has(HexUtils.key(n))) {
                        if (engine.map.getTerrainHeight(n.q, n.r) > uTerrainH + 20) {
                            occluded.push(a);
                            break;
                        }
                    }
                }
            }
        }
        return occluded;
    }
}

import { Agent } from "../core/Agent";
